import{z as B,x as p,o as E,c as A,q as o,j as l,D as e,d as r,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"回购市场与货币市场基金","description":"","frontmatter":{"title":"回购市场与货币市场基金","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/repo-mmf.md","filePath":"econ/repo-mmf.md","lastUpdated":1791063341000}'),d={name:"econ/repo-mmf.md"};function m(c,a,h,C,P,D){const t=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=o('<h1 id="回购市场与货币市场基金" tabindex="-1">回购市场与货币市场基金 <a class="header-anchor" href="#回购市场与货币市场基金" aria-label="Permalink to &quot;回购市场与货币市场基金&quot;">​</a></h1><div class="epigraph"><p>隔夜回购是抵押短债的批发市场；货币市场基金是其负债端的零售与公司现金池。两者同时停，就是影子挤兑的交易层。</p><footer>—— 对照 Duffie 对回购与 CCP 的讨论；Kacperczyk and Schnabl 的 MMF 风险承担</footer></div><p><a href="/econ/central-bank-balance-sheet">上一课</a>把 ON RRP 写进央行负债。缺口是私人侧：谁在做回购、谁持有 MMF。本课钉交易层，CBDC 下一课才谈零售负债替代。不重写 haircut 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双边与三方回购把国债/MBS 变成现金。MMF 稳定净值的承诺，使份额像存款却没有同等保险（2008 年 Reserve Primary）。2019 年 9 月的回购利率尖峰说明：即使抵押全是国债，中介的资产负债表空间也可以突然变贵。缺口是把短债生态连成一张图——现金池在左、杠杆在右——看谁在什么约束下向谁供给隔夜资金，而不是分别讲「货基」和「回购」两个词条。</p><p><span class="marginnote">术语翻译：「回购」就是用债券当抵押品借隔夜钱——今天把国债交给对手方、拿到现金，明天还钱付息、取回债券。对出资方来说这不是「买债券」，而是「有抵押的放贷」：对方违约就扣下债券，所以风险远小于无抵押拆借，利率也因此更低。</span></p><p><span class="marginnote">Copeland, Martin and Walker 的三方回购：清算银行日内垫资，交易商实际上把日内敞口滚成隔夜——改革动的是这条腿。Infante 对抵押品再利用。SEC 2014/2023 MMF 改革是制度，本课只取其改变了哪些激励。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画资金链：现金池 → MMF → 回购/CP → 交易商 → 对冲基金/抵押再质押。压力测试：国债供给、准备金、杠杆基金保证金同时变。政策：ON RRP 给 MMF 一个央行对手方，等于给影子负债一个地板；CCP 与保证金缓回购传染。与 GK：交易商净值是 \\(\\phi\\) 的微观对应——做市与融资都要过交易商自己的风险预算，预算收紧时全市场的隔夜价格一起动。</p>',9)),(E(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%B1%A0%22%5D%20--%3E%20MMF%5B%22%E8%B4%A7%E5%B8%81%E5%B8%82%E5%9C%BA%E5%9F%BA%E9%87%91%22%5D%0A%20%20MMF%20--%3E%20REPO%5B%22%E5%9B%9E%E8%B4%AD%20%2F%20CP%22%5D%0A%20%20REPO%20--%3E%20DL%5B%22%E4%BA%A4%E6%98%93%E5%95%86%22%5D%0A%20%20DL%20--%3E%20HF%5B%22%E6%9D%A0%E6%9D%86%E9%9C%80%E6%B1%82%22%5D%0A%20%20ONRRP%5B%22ON%20RRP%22%5D%20--%3E%20MMF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"稳定净值 + 可日赎 = 隐性看跌。2008 年 9 月 15 日 Lehman 破产，次日历史最老的 Reserve Primary Fund——1970 年发明货基产品的那只——因持有 7.85 亿美元 Lehman 商业票据，净值记到 0.97 美元。约束与动作要写全：机构现金池面对先到先得的赎回，于是赎回变成竞速，两周内约 3,000 亿美元流出优先级基金、涌进政府型基金；基金被迫抛 CP 回血，CP 利差跳升，连没碰过 Lehman 的好企业也发不出票。反事实由政策补齐：财政部临时担保份额、AMLF 接手货基手里的 ABCP、CPFF 直接下场买 CP，链路才重新接通。Kacperczyk and Schnabl 的解释在事前：机构型基金为留住现金池客户承担了更多风险，事前卖隐性保险；事后发起人自掏腰包补净值，证明隐担保是真期权——免费，直到不再免费。",-1)),(E(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LH%5B%22Lehman%20%E7%A0%B4%E4%BA%A7%EF%BC%8CReserve%20Primary%20%E5%87%80%E5%80%BC%E8%B7%8C%E5%88%B0%200.97%22%5D%20--%3E%20RUN%5B%22%E6%9C%BA%E6%9E%84%E7%8E%B0%E9%87%91%E6%B1%A0%E7%AB%9E%E9%80%9F%E8%B5%8E%E5%9B%9E%EF%BC%9A%E5%85%88%E5%88%B0%E5%85%88%E5%BE%97%22%5D%0A%20%20RUN%20--%3E%20SELL%5B%22%E5%9F%BA%E9%87%91%E6%8A%9B%E5%94%AE%E5%95%86%E4%B8%9A%E7%A5%A8%E6%8D%AE%E5%9B%9E%E8%A1%80%22%5D%0A%20%20SELL%20--%3E%20CPS%5B%22CP%20%E5%88%A9%E5%B7%AE%E8%B7%B3%E5%8D%87%22%5D%0A%20%20CPS%20--%3E%20GOOD%5B%22%E6%B2%A1%E7%A2%B0%20Lehman%20%E7%9A%84%E5%A5%BD%E4%BC%81%E4%B8%9A%E4%B9%9F%E5%8F%91%E4%B8%8D%E5%87%BA%E7%A5%A8%22%5D%0A%20%20GOV%5B%22%E6%94%BF%E7%AD%96%EF%BC%9A%E6%8B%85%E4%BF%9D%20%2B%20AMLF%20%2B%20CPFF%22%5D%20--%3E%20FIX%5B%22%E9%93%BE%E8%B7%AF%E9%87%8D%E6%96%B0%E6%8E%A5%E9%80%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">直觉类比：稳定净值像「永远按 1 元面值兑付」的承诺。一旦基金资产跌破 1 元，先赎回的人按 1 元全身而退，损失全部留给没走的人——于是所有人都抢着第一个走。银行挤兑的先动优势没有被消除，只是从柜台排队搬进了电子转账。</span></p><p>回购侧同一挤兑换了对手方。2019 年 9 月 16–17 日，公司缴税日撞上国债缴款日，财政部把银行准备金抽薄；杠杆基金与做市商受内部风险预算约束不再抬价接券，货基又在季末前收缩回购盘口。隔夜利率于是脱锚：SOFR 一夜从 2.2% 跳到 5.25%，有效联邦基金利率冲出目标区间上沿。反事实写在央行的回应里：隔夜与定期正回购先顶住，随后按月购入短期国库券，把准备金补回「充足」带；当时 ON RRP 几乎无人使用，说明问题不是地板太低，而是准备金落到了需求曲线的陡峭段。地板系统要靠量垫着——先修<a href="/econ/ior-corridor-floor">准备金利息与走廊</a>的几何在此兑现：锚没坏，量不够。</p><p>赎回螺旋的微观是时间一致性问题：份额按面值赎回、资产按市价变现，先赎的人拿走整块面值，损失留给没走的——稳定净值没有消除银行挤兑的先动优势，只把它藏进电子转账。MMF 侧是挤提，回购侧是配给，两侧在交易商的资产负债表上相遇，与影子课同一机制，只是合约名不同；所以政策也分两路，落在份额端（担保）与抵押端（便利与购券）。</p><p><span class="marginnote">术语翻译：「ON RRP」是央行向货基等机构提供的隔夜逆回购工具——机构把钱借给央行、以国债作抵押，次日拿回本息。它给隔夜现金一个央行保底价：私人对手方出的利率低于它时，钱就流去央行。所以它被称为「地板」，2019 年尖峰的问题不在地板高度，而在准备金总量不够。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写清算所默认基金的法律细节。下一课 CBDC 是公共零售负债，可能改写现金池要不要经过 MMF。不把 2019 尖峰写成唯一校准：缴税与缴款的日历错位每年都有，脱锚只发生在准备金最薄的那一次。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回购与 MMF 是影子短债的交易层与零售层。</li><li>Reserve Primary 破净把隐性看跌兑成显性挤兑；担保与便利把链路接回。</li><li>2019 尖峰：地板系统下量不够，隔夜利率照样脱锚。</li><li>ON RRP 把部分货基接到央行地板。</li><li>出处：Gorton–Metrick 回购；Kacperczyk–Schnabl MMF；Copeland, Martin and Walker 三方回购；Duffie 市场结构讨论。</li></ul>',8))])}const f=B(d,[["render",m]]);export{M as __pageData,f as default};
